#[derive(Debug)]
pub enum CompilationUnit<'a> {
    // CompilationUnit = OrdinaryCompilationUnit
    Alt0 {
        ordinary_compilation_unit: &'a OrdinaryCompilationUnit<'a>,
        span: Span,
    },
    // CompilationUnit = CompactCompilationUnit
    Alt1 {
        compact_compilation_unit: &'a CompactCompilationUnit<'a>,
        span: Span,
    },
    // CompilationUnit = ModularCompilationUnit
    Alt2 {
        modular_compilation_unit: &'a ModularCompilationUnit<'a>,
        span: Span,
    },
    Amb(&'a [ParseTree<'a>]),
}
// OrdinaryCompilationUnit = PackageDeclaration? Layout ImportDeclaration* Layout
// TypeDeclaration*
#[derive(Debug)]
pub enum OrdinaryCompilationUnit<'a> {
    Alt0 {
        package_declaration: &'a Opt0<'a>,
        layout_1: &'a Layout<'a>,
        import_declarations: &'a Star0<'a>,
        layout_3: &'a Layout<'a>,
        type_declarations: &'a Star1<'a>,
        span: Span,
    },
    Amb(&'a [ParseTree<'a>]),
}
